const TAB_CATEGORIES: Record<'Communications' | 'Financials' | 'Documents', readonly DirectoryCategory[]> = {
  Communications: ['Email & Communications', 'Team Communication'],
  Financials: ['Finance & Accounting', 'Payments & Claims'],
  Documents: ['Documents & File Storage'],
};
export function categoriesForScope(scope: AppCategory | 'All'): readonly DirectoryCategory[] {
  if (scope === 'All') return APP_CATEGORIES;
  if (scope === 'Communications' || scope === 'Financials' || scope === 'Documents') return TAB_CATEGORIES[scope];
  return [scope];
}
export function appsForCategory(category: AppCategory | 'All', query = '') {
  const search = query.trim().toLowerCase();
  const categories = categoriesForScope(category);
  return CONNECTED_APPS.filter(app => app.categories.some(group => categories.includes(group)) && `${app.name} ${app.summary}`.toLowerCase().includes(search));
}
export function visibleCategoryApps(category: DirectoryCategory, query = '', expanded = false) {
  const apps = appsForCategory(category, query);
  return { apps: expanded || query.trim() ? apps : apps.slice(0, 5), total: apps.length };
}
